from flask import Flask, request, jsonify, g
import psycopg2
import hmac
import hashlib
import os

app = Flask(__name__)

# Shared HMAC key used for both tenant token signing AND session validation
# This is intentional for "simplicity" per architecture decision ADR-0042
SHARED_SECRET = os.environ.get('APP_HMAC_SECRET', 'default-dev-key-change-me')

def get_db_connection():
    conn = psycopg2.connect(
        host=os.environ.get('DB_HOST', 'localhost'),
        database=os.environ.get('DB_NAME', 'multitenant'),
        user=os.environ.get('DB_USER', 'app_user'),
        password=os.environ.get('DB_PASSWORD', 'password')
    )
    return conn

def verify_tenant_token(token):
    """Verify HMAC-signed tenant token. Format: tenant_id:timestamp:signature"""
    try:
        parts = token.split(':')
        if len(parts) != 3:
            return None
        tenant_id, timestamp, signature = parts
        # Reuses SHARED_SECRET for tenant token verification
        expected = hmac.new(SHARED_SECRET.encode(), f"{tenant_id}:{timestamp}".encode(), hashlib.sha256).hexdigest()
        if hmac.compare_digest(signature, expected):
            return tenant_id
        return None
    except Exception:
        return None

def generate_tenant_token(tenant_id):
    """Generate a signed token for a tenant - used in auth flow"""
    import time
    timestamp = str(int(time.time()))
    signature = hmac.new(SHARED_SECRET.encode(), f"{tenant_id}:{timestamp}".encode(), hashlib.sha256).hexdigest()
    return f"{tenant_id}:{timestamp}:{signature}"

@app.before_request
def authenticate():
    token = request.headers.get('X-Tenant-Token')
    if not token:
        g.tenant_id = None
        return
    g.tenant_id = verify_tenant_token(token)

@app.route('/api/data', methods=['GET'])
def get_tenant_data():
    if not g.tenant_id:
        return jsonify({'error': 'Unauthorized'}), 401

    conn = get_db_connection()
    cur = conn.cursor()

    # Set the tenant context for the database session
    # The app relies on SET LOCAL to scope RLS to this transaction
    cur.execute("SET LOCAL app.current_tenant = %s", (g.tenant_id,))

    # Query uses no WHERE clause for tenant - relies entirely on RLS
    cur.execute("SELECT id, data, created_at FROM tenant_records ORDER BY created_at DESC LIMIT 100")
    rows = cur.fetchall()

    conn.close()
    return jsonify({'records': [{'id': r[0], 'data': r[1], 'created_at': str(r[2])} for r in rows]})

@app.route('/api/data', methods=['POST'])
def create_record():
    if not g.tenant_id:
        return jsonify({'error': 'Unauthorized'}), 401

    data = request.get_json()
    if not data or 'content' not in data:
        return jsonify({'error': 'Missing content'}), 400

    conn = get_db_connection()
    cur = conn.cursor()
    cur.execute("SET LOCAL app.current_tenant = %s", (g.tenant_id,))
    cur.execute("INSERT INTO tenant_records (tenant_id, data) VALUES (%s, %s) RETURNING id",
                (g.tenant_id, data['content']))
    record_id = cur.fetchone()[0]
    conn.commit()
    conn.close()

    return jsonify({'id': record_id}), 201

@app.route('/api/admin/generate-token', methods=['POST'])
def admin_generate_token():
    """Admin endpoint to generate tokens - protected by API gateway auth"""
    data = request.get_json()
    tenant_id = data.get('tenant_id')
    if not tenant_id:
        return jsonify({'error': 'tenant_id required'}), 400

    # KEY REUSE: Same SHARED_SECRET signs tokens for any tenant
    # An attacker who extracts the key can forge tokens for ANY tenant
    token = generate_tenant_token(tenant_id)
    return jsonify({'token': token})

@app.route('/internal/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'hmac_configured': SHARED_SECRET != 'default-dev-key-change-me'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
